mapper.select:
SELECT t1.id, t1.`name`, t1.start_date, t1.end_date, t1.target_amount, t1.create_time, t1.`status` FROM `sys_active_center` t1 WHERE t1.del_flag = 0
AND t1.`name` LIKE concat('%',#{param.name},'%')
AND t1.`status` = #{param.status}
AND t1.start_date >= #{param.startDay}
AND t1.end_date <= #{param.endDay}
ORDER BY t1.create_time DESC
